from flask import Flask, request, jsonify, abort
from db import Session, Item

app = Flask(__name__)
API_KEY = open('key.txt').read().strip()

@app.before_request
def check_key():
    if request.headers.get('X-API-Key') != API_KEY:
        abort(401)

@app.get('/items')
def list_items():
    with Session() as s:
        return jsonify([i.to_dict() for i in s.query(Item).all()])

@app.post('/items')
def add_item():
    data = request.get_json()
    with Session() as s:
        item = Item(name=data['name'], price=data['price'])
        s.add(item); s.commit()
        return jsonify(item.to_dict()), 201

@app.get('/items/<int:item_id>')
def get_item(item_id):
    with Session() as s:
        item = s.get(Item, item_id) or abort(404)
        return jsonify(item.to_dict())

